import torch


def run(grad_output, input, target, reduction, beta):
    return torch.ops.aten.smooth_l1_loss_backward(
        grad_output, input, target, reduction, beta
    )


def run_correctness(grad_output, input, target, reduction, beta):
    output = torch.ops.aten.smooth_l1_loss_backward(
        grad_output.float(),
        input.float(),
        target.float(),
        reduction,
        beta,
    )
    return output.to(input.dtype)


def gen_inputs(ctx, device):
    import torch

    go_dtype = getattr(torch, ctx["grad_output__dtype"])
    in_dtype = getattr(torch, ctx["input__dtype"])
    tg_dtype = getattr(torch, ctx["target__dtype"])
    go_shape = tuple(ctx["grad_output__shape"])
    in_shape = tuple(ctx["input__shape"])
    tg_shape = tuple(ctx["target__shape"])
    # test_smooth_l1_loss_backward_beta_zero_equal_inputs_cuda_behavior:
    # equal inputs with beta=0 yield NaN gradients on CUDA.
    return {
        "grad_output": torch.ones(go_shape, dtype=go_dtype, device=device),
        "input": torch.zeros(in_shape, dtype=in_dtype, device=device),
        "target": torch.zeros(tg_shape, dtype=tg_dtype, device=device),
    }


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch

    ref = ref_outputs[0].detach().to("cpu").to(torch.float64)
    sol = sol_outputs[0].detach().to("cpu").to(torch.float64)
    if ref.shape != sol.shape:
        return {"passed": False, "message": f"shape {sol.shape} vs {ref.shape}"}
    both_nan = torch.isnan(ref) & torch.isnan(sol)
    both_posinf = torch.isposinf(ref) & torch.isposinf(sol)
    both_neginf = torch.isneginf(ref) & torch.isneginf(sol)
    finite = torch.isfinite(ref) & torch.isfinite(sol)
    close = torch.zeros_like(ref, dtype=torch.bool)
    close[finite] = (ref[finite] - sol[finite]).abs() <= 2e-2 + 2e-2 * ref[finite].abs()
    ok = (close | both_nan | both_posinf | both_neginf).all().item()
    return {"passed": bool(ok), "message": "", "metrics": {}}
